@section('title', 'Özel sohbet · '.$chat->hotel->name)
@section('content')
@if(!$admin)<main class="wrap chat-page">@else<div class="chat-admin-page">@endif<section class="detail-panel chat-box"><div class="chat-heading"><div><span class="detail-eyebrow">{{ $chat->status==='archived'?'ARŞİVLENMİŞ SOHBET':'ÖZEL SOHBET' }}</span><h1>{{ $chat->hotel->name }}</h1><p>{{ $chat->user?->name ?? $chat->guest_name }} · Yalnızca sohbetin tarafları ve yetkili yöneticiler görebilir.</p></div>@if($chat->status==='open')<form method="post" action="{{ $partnerPanel ? route('panel.hotel-chats.archive',$chat) : route('hotel-chats.archive',$chat) }}">@csrf<button class="btn ghost" type="submit">Sohbeti arşivle</button></form>@endif</div>
<div class="chat-messages">@forelse($chat->messages as $message)<article data-id="{{ $message->id }}" class="chat-message {{ $message->sender_user_id && $message->sender_user_id===(auth()->id())?'mine':'' }}"><strong>{{ $message->sender?->name ?? ($message->sender_type==='owner'?'Tesis yetkilisi':($message->sender_type==='admin'?'Antalya Pet Otel':($message->sender_type==='guest'?$chat->guest_name:'Müşteri'))) }}</strong><p>{{ $message->body }}</p><time>{{ $message->created_at?->format('d.m.Y H:i') }}</time></article>@empty<p>Henüz mesaj yok.</p>@endforelse</div>
