@if($chat->status==='open')<script>
(()=>{const list=document.querySelector('.chat-messages');if(!list)return;let last=Math.max(0,...Array.from(list.querySelectorAll('.chat-message')).map(x=>Number(x.dataset.id||0)));const poll=async()=>{try{const url=@json(($partnerPanel ? route('panel.hotel-chats.poll',$chat) : route('hotel-chats.poll',$chat)).'?after=');const r=await fetch(url.concat(last),{headers:{Accept:'application/json'},credentials:'same-origin',cache:'no-store'});if(!r.ok)return;const d=await r.json();for(const m of d.messages){if(m.id<=last)continue;last=m.id;const el=document.createElement('article');el.className='chat-message'+(m.mine?' mine':'');const b=document.createElement('strong');b.textContent=m.sender;const p=document.createElement('p');p.textContent=m.body;const t=document.createElement('time');t.textContent=m.created_at;el.append(b,p,t);list.append(el);list.scrollTop=list.scrollHeight;}}catch(e){}};setInterval(poll,5000);})();
</script>@endif
